import clsx from 'clsx';
import React, { ComponentPropsWithRef, useState } from 'react';
import type { TTailwindIconClass } from '@rbx/foundation-tailwind/classes';
import { Icon } from './Icon';
import { IconButton } from './IconButton';
import { Media } from './Media';

export type TBreadcrumbItem = {
  /** The label text for the breadcrumb item. */
  label: string;
  /** Optional href for clickable breadcrumb items. */
  href?: string;
  /** Optional leading icon class name. */
  leadingIcon?: TTailwindIconClass;
  /** Optional media image source. */
  mediaSrc?: string;
  /** Optional click handler for the breadcrumb item. */
  onClick?: (e: React.MouseEvent) => void;
};

export type TBreadcrumbsProps = Omit<ComponentPropsWithRef<'nav'>, 'children'> & {
  /** Array of breadcrumb items to display. */
  items: TBreadcrumbItem[];
  /** aria-label for the breadcrumb navigation. */
  ariaLabel: string;
  /** aria-label for expanding breadcrumb items. */
  expansionAriaLabel: string;
  /** Optional maximum number of items to show before collapsing. When collapsed, shows first item, ellipsis button, and last item. */
  maxItems?: number;
};

const BreadcrumbSeparator = () => {
  return (
    <div className='flex items-center justify-center shrink-0 width-600'>
      <span className='text-body-medium content-default'>/</span>
    </div>
  );
};

type TBreadcrumbItemComponentProps = {
  item: TBreadcrumbItem;
  isActive: boolean;
};

const BreadcrumbItemComponent: React.FC<TBreadcrumbItemComponentProps> = ({ item, isActive }) => {
  const { label, href, leadingIcon, mediaSrc, onClick } = item;

  const content = (
    <div className={clsx('flex items-center gap-small shrink-0 height-600')}>
      {leadingIcon && <Icon name={leadingIcon} size='XSmall' className='content-emphasis' />}
      {mediaSrc && (
        <div className='shrink-0 size-500'>
          <Media
            src={mediaSrc}
            alt={label}
            aspectRatio='1:1'
            containerClassName='radius-small clip'
          />
        </div>
      )}
      <span
        className={clsx('text-no-wrap', {
          'content-emphasis text-title-medium': isActive,
          'content-default text-body-medium': !isActive
        })}>
        {label}
      </span>
    </div>
  );

  if (href && !isActive) {
    return (
      <a
        href={href}
        onClick={onClick}
        className={clsx('flex items-center shrink-0 focus-visible:outline-focus radius-small')}
        style={{ textDecoration: 'none' }}>
        {content}
      </a>
    );
  }

  if (onClick && !isActive) {
    return (
      <button
        type='button'
        onClick={onClick}
        className={clsx(
          'flex items-center shrink-0 cursor-pointer padding-none bg-none focus-visible:outline-focus radius-small'
        )}
        style={{ border: 'none' }}>
        {content}
      </button>
    );
  }

  return (
    <div className='flex items-center shrink-0' aria-current={isActive ? 'page' : undefined}>
      {content}
    </div>
  );
};

export const Breadcrumbs: React.FC<TBreadcrumbsProps> = ({
  items,
  maxItems,
  ariaLabel,
  expansionAriaLabel,
  className,
  ...otherProps
}) => {
  const [isExpanded, setIsExpanded] = useState(false);

  const shouldCollapse = maxItems != null && items.length > maxItems && !isExpanded;

  let displayItems: TBreadcrumbItem[] = items;
  let hasCollapsed = false;

  if (shouldCollapse) {
    // Show first item, ellipsis button, and last item only
    displayItems = [items[0], items[items.length - 1]];
    hasCollapsed = true;
  }

  const handleExpandClick = () => {
    setIsExpanded(true);
  };

  return (
    <nav
      aria-label={ariaLabel}
      className={clsx('flex items-center height-1000', className)}
      {...otherProps}>
      <ol
        className='flex items-center padding-none margin-none gap-none'
        style={{ listStyle: 'none' }}>
        {displayItems.map((item, index) => {
          const isActive = index === displayItems.length - 1;
          return (
            <React.Fragment key={item.href || `${item.label}-${index}`}>
              {hasCollapsed && index === 1 && (
                <React.Fragment>
                  <li>
                    <IconButton
                      icon='icon-filled-three-dots-horizontal'
                      ariaLabel={expansionAriaLabel}
                      size='XSmall'
                      variant='Standard'
                      onClick={handleExpandClick}
                      className='size-600 min-height-600 max-height-600'
                    />
                  </li>
                  <li>
                    <BreadcrumbSeparator />
                  </li>
                </React.Fragment>
              )}
              <li>
                <BreadcrumbItemComponent item={item} isActive={isActive} />
              </li>
              {index < displayItems.length - 1 && (
                <li>
                  <BreadcrumbSeparator />
                </li>
              )}
            </React.Fragment>
          );
        })}
      </ol>
    </nav>
  );
};

Breadcrumbs.displayName = 'Breadcrumbs';
